"""Render inspectable source, registration and inference ledgers from recipes."""
import pathlib,json,re,hashlib,sys
p=pathlib.Path(__file__).parent;data=pathlib.Path('src/content/topics/warring-states/data')
m=json.load(open(p/'sources.json'));log=json.load(open(p/'raw/fetch-log.json'));ext=json.load(open(p/'extra-georef-manifest.json'))
def loadfit(id):
 for f in [p/'work'/f'svg-{id}-fit.json',p/'work'/f'raster-{id}-fit.json',p/'check'/f'raster-{id}-fit.json',p/'check'/f'extra-{id}-fit.json']:
  if f.exists():return json.load(open(f))
 return None
def esc(s):return str(s).replace('|',' / ').replace('\n',' ')
def cps(id):
 src=m.get('svg',{}).get(id) or m.get('raster',{}).get(id)
 if src:
  if src.get('controlPointsFrom'):return cps(src['controlPointsFrom'])
  return src.get('controlPoints',[])
 return ext.get('unregistered',{}).get(id,{}).get('diagnosticControlPoints',[])
header=['# Warring States geography: source and inference ledger','','Map data: **Creative Commons Attribution-ShareAlike 4.0 International** (https://creativecommons.org/licenses/by-sa/4.0/). Attribution, original licences and changes are listed below. Natural Earth inputs are public domain; Wikipedia coordinate text is attributed separately. No CHGIS geometry, Tan atlas scans, modern administrative proxies, or invented geographic polygons enter the released map.','','## Source correction and acceptance limits','','G9 is a point-distribution map, not a polygon map: direct visual inspection disproved the specification’s proposed raster-category method. G10, already on the approved list, supplies the early period polygons instead. G9 is only a capital/location cross-check. **K1–K3 reuse undated period geography and are not year-exact reconstructions.** G10 has no bounded Chen, Cai, Tan, Sui, Shen, Xi, Deng, Yu, Guo, Huo, Geng, Liang, Rui, Yong and other minor annexation units; those changes cannot be digitized as whole-state transfers and are not invented. K2/K3 do not show fabricated territorial expansion.','','Registration budgets are 5 km for G1, 25 km for primary regional state maps and 40 km for small/period maps (maximum in-sample residual; leave-one-out statistics are also reported). G11 exceeds the 25 km budget (maximum 66.657 km; leave-one-out maximum 86.927 km) and is excluded from all keyframe geometry. K9–K11 instead carry forward the registered G8 280 BCE outlines; the intervening boundaries are not reconstructed. G8 has maximum 18.958 km and leave-one-out maximum 21.033 km. G9 exceeds its check-only 40 km budget slightly and supplies point identities, never polygons. G15 exceeds 25 km and supplies no frame geometry. G13/G17 retain only 5/8 secure controls; G16 has none: all are diagnostic/reference-only and excluded from frame selectors and comparison dependencies. Thus the request for twelve trustworthy controls on every one of the eighteen maps is **not met**; no synthetic control points or artificially low RMS are claimed.','','Earlier source surveys in the approved spec found no usable dated boundary relations in OHM for this region/period. OHM is generally CC0, subject to feature exceptions; no OHM geometry is used here. CHGIS V6 starts at 221 BCE and its redistribution EULA excludes downloadable reuse without written agreement: not downloaded or redistributed. The © Tan Qixiang atlas is not traced locally; Commons authors’ own declared references to it are recorded in their metadata, without claiming independent permission from the atlas publisher.','','## Map downloads','','All eighteen Commons maps have a local file, API author/licence metadata and SHA-256 in raw/fetch-log.json (raw is gitignored). Full canonical originals were recovered where available; remaining published renders are clearly identified. Raw pixels are not shipped to the application. Derivative flat masks copy visible published source edges in source-pixel coordinates: this is tracing, not invented state geometry.','', '| Map | Author | Licence | Local input and SHA-256 | Role |','|---|---|---|---|---|']
for id,v in log.items():
 if not id.startswith('G'):continue
 author=re.sub('<[^>]*>','',v['author']);entry=f"{v['file']} ({v.get('downloadKind','download')}); {v['sha256']}"
 for key in ['originalDownload','registrationRender']:
  if key in v:entry+=f"; {key}: {v[key]['file']} / {v[key]['sha256']}"
 header.append(f"| [{id}] [{esc(v['title'])}]({v['page']}) | {esc(author)} | [{v['license']}]({v.get('licenseUrl','')}) | {esc(entry)} | {esc(m['datasets'][id]['role'])} |")
header+=['','## Registration reports and control points','','RMS, maximum, and leave-one-out RMS are geographic great-circle distances in kilometres. These describe map alignment only; they do not quantify the source map’s historical accuracy. CPs use source pixels/SVG units; exact Wikipedia query responses and coordinate audit fragments are retained alongside the recipes. NE/G1 matches recover a known shared modern dataset, so their tiny residuals are not independent archaeological evidence.','']
for id in ['G'+str(i) for i in range(1,19)]:
 fit=loadfit(id);pts=cps(id)
 header+=['### '+id,'']
 if fit:header+=[f"{len(pts)} controls; {fit['model']}; RMS **{fit['rmsKm']:.3f} km**, maximum **{fit['maxKm']:.3f} km**; leave-one-out RMS **{fit['looRmsKm']:.3f} km**, maximum **{fit['looMaxKm']:.3f} km**.",'']
 else:header+=['No defensible full registration: reference-only; no RMS claimed.','']
 if id in ext.get('unregistered',{}):header+=[ext['unregistered'][id]['reason'],'']
 header+=['| Control | Longitude, latitude | Source x, y | Coordinate provenance |','|---|---|---|---|']
 for pt in pts:header.append(f"| {esc(pt['name'])} | {', '.join(map(str,pt['lnglat']))} | {', '.join(map(str,pt['svg']))} | {esc(pt.get('coordinateSource','Same published base; see coordinate audits'))} |")
 header+=['']
frames=['## Control keyframes','','| Frame | Date | Sources; method and inference | Source licence → derivative licence | Registration model; RMS / max km | Comparison image |','|---|---|---|---|---|---|']
frame_sources={'K1':['G10'],'K2':['G10'],'K3':['G10'],'K4':['G3','G10'],'K5':['G3','G10'],'K6':['G3','G7'],'K7':['G7'],'K8':['G8'],'K9':['G8'],'K10':['G8'],'K11':['G8']}
for k in m['keyframes']:
 ids=frame_sources[k['id']];rs=[]
 for id in ids:
  fit=loadfit(id)
  if fit:rs.append(f"{id}: {fit['model']}; {fit['rmsKm']:.3f} / {fit['maxKm']:.3f}")
 steps=' '.join(dict.fromkeys(s['note'] for s in k['steps']))
 frames.append(f"| {k['id']} | {abs(int(k['t']))} BCE | {esc(k['method']+'; '+steps)} | {'; '.join(log[g]['license'] for g in ids if g in log)} → CC BY-SA 4.0 | {'; '.join(rs)} | check/geo-{k['id']}.png |")
frames+=['','Inference-based frames: **K1, K2, K3, K4’s G10 supplements, K5, K6, K9’s G8 carry-forward, K10, K11**. K6 borrows 350 BCE Han/Zhao/Wei divisions within the fifth-century Jin outline; the remaining source area is labelled residual Jin, not a fabricated city-centred enclave. K9 carries forward 280 BCE geography to 260 BCE without asserting the intervening changes; Zhou has no bounded G8 face and is omitted. K10 reassigns only the whole Han and Lu source components. K11 is the schematic union of these G8-derived ranges, not a reconstruction of the Qin imperial boundary; no Lingnan, steppe, or unbounded extra Yue land is added. Wey’s dependent ruling house survived until 209 BCE; the imperial fill does not date its abolition. No optional K12 is supplied.','','The shared coastline buffer-gap step dropped Qin in K10 even though it existed in composed inputs. This topic therefore disables that optional buffer step, runs the unchanged shared simplifier, then intersects each frame with real NE land in shore-clip.ts. Every holder is checked for retention, all frames are re-exported into one shared topology and rings rechecked. No gap-ownership buffer is used. Area-retention diagnostics in area-audit.json distinguish dissolved internal seams from missing territory: the largest coastline/region clipping changes are early Ju (about 22%) and G8 Yan (about 25%, including parts outside the regional plate); these remain source-alignment limits, not inferred annexations. G3 vector network is taken directly from the published `Borders 5 BC states` SVG paths, then polygonized. The source’s open coastal ends are closed against real Natural Earth coastline, with 1 km snapping and a 40 km gap tolerance. Bounded G10 Ba/Ju/Yue components supplement omissions. These source mixes and the unquantified historical error remain visible in approximate labels and feature certainty. G7/G8 textured relief required flat masks traced in original source pixels, whose overlays are in check/raster-*-trace-overlay.png. G11’s classified mask and original registration reports are retained only as diagnostic records; no G11 edge enters the released control geometry. G13/G16/G17 do not supply geometry or frame checks. No synthetic controls have been added to force a registration pass.','','## Rivers and regional plate','','public/geo/warring-states-region.json: Natural Earth 10m land clipped to [100,20,125,44], DP 1.5 km; only the actual unclipped shoreline becomes kind:coast. The engine builds the outside frame and restricts the camera to [98,18,127,45.5]. public/geo/warring-states-rivers.json: G1 open river paths, parsed with the shared SVG path parser, affine registered on 15 real NE river endpoints, DP 400 m. Both are static local files. Yellow River common upper/middle reaches are retained; the post-1855 lower course is absent. Reconstructed pre-602 BCE branch has to:-0602; reconstructed later branch has from:-0602,to:0011; Ji is reconstructed throughout the topic. G1’s displayed geographic coverage limits western/southern tributary completeness; no absent reach was sketched in. Optional ancient coast and unsupported ancient wall lines are omitted.','','## Reproduction','','1. python3 scripts/geo/warring-states/fetch-commons.py (verified cache; full observed hashes retained).','2. Prepare source registration fragments and inspect their control-point/trace overlays. The checked-in pixel vertices, CP arrays and original source hashes are the reproducible tracing record.','3. python3 scripts/geo/warring-states/merge-registrations.py; pnpm tsx scripts/geo/warring-states/build-region-rivers.ts; pnpm tsx scripts/geo/warring-states/extract-network.ts.','4. pnpm tsx scripts/geo/lib/georef-svg.ts --topic warring-states; pnpm tsx scripts/geo/lib/georef-raster.ts --topic warring-states. Registration-only maps and failed-budget references are not territorial selectors.','5. pnpm tsx scripts/geo/warring-states/build-keyframes.ts; pnpm tsx scripts/geo/lib/compose.ts --topic warring-states; pnpm tsx scripts/geo/lib/simplify.ts --topic warring-states --out scripts/geo/warring-states/work/control-nocoast.json; pnpm tsx scripts/geo/warring-states/shore-clip.ts; pnpm tsx scripts/geo/warring-states/finalize-control.ts; pnpm tsx scripts/geo/lib/colour-holders.ts --topic warring-states --write; pnpm tsx scripts/geo/warring-states/holder-colors.ts (exports the assigned colours without changing entities).','6. pnpm tsx scripts/geo/lib/colour-holders.ts --topic warring-states; pnpm tsx scripts/geo/warring-states/prepare-check-references.ts; pnpm tsx scripts/geo/lib/check.ts --topic warring-states (outputs check/geo-K*.png); inspect every image. pnpm validate is the requested content gate; no build/test/e2e/shoot was run.','']
geo='\n'.join(header+frames)+'\n';(p/'SOURCES-GEO.md').write_text(geo)
if '--geo-only' in sys.argv:
 print('Wrote geographic source ledger only');sys.exit(0)
md=['# Spring and Autumn and Warring States: sources','','**Draft English text; Chinese translation and human review pending.** Map data are CC BY-SA 4.0, with attribution and upstream licences below. All borders are approximate; registration error does not establish ancient territorial accuracy. The complete geographic control-point ledger is scripts/geo/warring-states/SOURCES-GEO.md. Known factual/site verification items are in ../AUDIT.md.','','## Geographic source and inference limits','']+header[header.index('G9 is a point-distribution map, not a polygon map: direct visual inspection disproved the specification’s proposed raster-category method. G10, already on the approved list, supplies the early period polygons instead. G9 is only a capital/location cross-check. **K1–K3 reuse undated period geography and are not year-exact reconstructions.** G10 has no bounded Chen, Cai, Tan, Sui, Shen, Xi, Deng, Yu, Guo, Huo, Geng, Liang, Rui, Yong and other minor annexation units; those changes cannot be digitized as whole-state transfers and are not invented. K2/K3 do not show fabricated territorial expansion.'):header.index('## Registration reports and control points')]+frames[:frames.index('## Rivers and regional plate')]
md+=['## Movement routes','','Lines are source-supported **schematic itineraries** between named-place anchors, not surveyed ancient roads or exact marching paths. Coordinate and textual reconciliation limits are stated individually.','', '| Route | From–to | Ordered stations, coordinates and evidence |','|---|---|---|']
ss=json.load(open(data/'sources.json'))['sources'];by={r['id']:r for r in ss};moves=json.load(open(data/'movements.json'))
for i,r in enumerate(moves):
 src=by.get('S'+str(170+i),{});md.append(f"| {r['id']} | {r['from']} → {r['to']} | {esc(src.get('note',{}).get('en','See source list.'))} |")
md+=['','## Historical and map source entries','', '<!-- sources:begin (generated by scripts/sources-md.ts from sources.json; edit sources.json) -->','']
for r in ss:
 text=r['text']['en'];md+=['### '+r['id'],'',f"[{text}]({r['url']})" if r.get('url') else text,'']
 if r.get('note'):md+=[r['note']['en'],'']
md+=['<!-- sources:end -->',''];(data/'SOURCES.md').write_text('\n'.join(md))
print('Wrote source ledgers')
